def _sheet(num, title, sub, layers):
    rows = "".join(f"<li><b>{i + 1}. {a}</b> — {b}</li>" for i, (a, b) in enumerate(layers))
    return f'<p class="e-note"><b>Лист {num}. {title}.</b> {sub}.</p><ol class="e-ul">{rows}</ol>'


